 public static object Run(){var s=SceneManager.GetActiveScene();if(Application.isPlaying||s.isDirty||!s.path.EndsWith("Level_B5_Circular.unity"))throw new Exception("Saved B5 Edit scene required");var root=s.GetRootGameObjects().Single(g=>g.name.StartsWith("B5_Circular")).transform;var center=new Vector3(-22,-82,18);var renderers=root.GetComponentsInChildren<Renderer>(true).Where(r=>r.gameObject.activeInHierarchy&&Vector3.Distance(new Vector3(r.bounds.center.x,0,r.bounds.center.z),new Vector3(-22,0,18))<8.2f).ToArray();var result=new{scene=s.path,dirty=s.isDirty,nearby=renderers.Select(r=>new{path=P(r.transform),position=V(r.transform.position-center),rotation=V(r.transform.eulerAngles),center=V(r.bounds.center-center),size=V(r.bounds.size),mesh=r.GetComponent<MeshFilter>()?AssetDatabase.GetAssetPath(r.GetComponent<MeshFilter>().sharedMesh):"",materials=r.sharedMaterials.Select(m=>m?m.name:null)}).ToArray(),doors=root.Find("Pocket_Doors_Open").Cast<Transform>().Where(t=>Vector3.Distance(t.position,center)<8).Select(t=>new{path=P(t),position=V(t.position-center),rotation=V(t.eulerAngles),children=t.Cast<Transform>().Select(c=>new{c.name,active=c.gameObject.activeSelf})}).ToArray(),lights=root.GetComponentsInChildren<Light>(true).Select(l=>new{path=P(l.transform),enabled=l.enabled,active=l.gameObject.activeInHierarchy,position=V(l.transform.position),rotation=V(l.transform.eulerAngles),l.intensity,l.range,l.spotAngle,color=V(new Vector3(l.color.r,l.color.g,l.color.b)),type=l.type.ToString(),shadows=l.shadows.ToString()}).ToArray(),hierarchy=root.GetComponentsInChildren<Transform>(true).Select(t=>new{path=P(t),position=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf}).ToArray()};var dir=Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_C02_Refine/"));Directory.CreateDirectory(dir);if(File.Exists(dir+"before.json"))throw new Exception("Baseline exists");File.WriteAllText(dir+"before.json",JsonConvert.SerializeObject(result,Formatting.Indented));return new{scene=s.path,nearby=result.nearby,doors=result.doors,lights=result.lights.Where(l=>Vector3.Distance(new Vector3(l.position[0],-82,l.position[2]),center)<8)};}
